const express = require('express');
const { create } = require('kubo-rpc-client');
const db = require('../db');

const ipfs = create({ url: process.env.KUBO_RPC_URL || 'http://127.0.0.1:5001' });
const app = express();

app.get('/api/ipfs/mfs/list', async (req, res) => {
  const { vaultId } = req.query;
  if (!vaultId) {
    return res.status(400).json({ error: 'vaultId parameter required' });
  }

  // Assert user is the authorized owner of the vault
  const vault = await db('user_vaults')
    .where({ id: vaultId, user_id: req.user.id })
    .first();

  if (!vault) {
    return res.status(403).json({ error: 'Access denied: Vault not found or not owned by user' });
  }

  try {
    const files = [];
    for await (const file of ipfs.files.ls(`/vaults/${vaultId}`)) {
      files.push({
        name: file.name,
        type: file.type,
        size: file.size,
        cid: file.cid.toString()
      });
    }

    return res.json({ vaultId, files });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

module.exports = app;
